from pathlib import Path
import json,numpy as np,matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path(__file__).resolve().parents[1];plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'figure.dpi':160})
rows=json.loads((R/'raw/interval_summary.json').read_text());L=float(json.loads((R/'raw/interval_lower_certificate.json').read_text())['certified_energy_lower'])
fig,ax=plt.subplots(figsize=(8,4.8));names=['P samples','f noise .005','f noise .01','f noise .02','f noise .05','No later samples'];vals=[float(r['common_capacity_upper']) for r in rows];colors=['#128b8b']*5+['#a7b3c2'];ax.barh(np.arange(6),vals,color=colors);ax.axvline(L,color='#b14343',ls='--',lw=1.6,label='Universal blind / opaque-f lower bound');ax.set_yticks(np.arange(6),names);ax.invert_yaxis();ax.set_xlim(0,.51);ax.set_xlabel('Usable storage capacity (normalized)');ax.set_title('Same mature predictive filter, different observation contracts',loc='left',weight='bold');
for i,v in enumerate(vals):ax.text(v+.004,i,f'{v:.6f}',va='center',fontsize=9)
ax.legend(loc='lower left',bbox_to_anchor=(0,-.29),frameon=False);fig.text(.125,.01,'All rows: h=.1, delay=.05, P=.5, common initial SOC; exact recovery at H=20.\nBars are feasible upper bounds, not sensor-wise optima. Frequency rows retain initial-stage side information.',fontsize=8);fig.tight_layout(rect=[0,.09,1,1]);fig.savefig(R/'figures/resource_contracts.png');fig.savefig(R/'figures/resource_contracts.pdf');plt.close(fig)
t=np.linspace(0,5,2001);g=lambda x:np.where(x>=0,np.maximum(x,0)*np.exp(-np.maximum(x,0)),0);base=g(t);upper=base+g(np.minimum(t,1));lower=base;mid=(upper+lower)/2
fig,axs=plt.subplots(2,1,figsize=(8,5.5),sharex=True);axs[0].fill_between(t,lower,upper,color='#d7e8f5',label='All low-start free responses');axs[0].plot(t,mid,c='#b14343',lw=1.6,label='Common noisy observation');
for r in [.01,.3,1.2,3,5]:axs[0].plot(t,base+g(t-r),lw=.8,alpha=.6)
axs[0].set_ylabel('Frequency output');axs[0].legend(frameon=False,ncol=2,fontsize=8);axs[0].set_title('Whole-family opacity follows from step-response range',loc='left',weight='bold');axs[1].plot(t,(upper-lower)/2,c='#b14343');axs[1].axhline(1/(2*np.e),color='#5e6873',ls='--',label='Sharp radius 1/(2e)');axs[1].set_xlabel('Time after reconnection (normalized)');axs[1].set_ylabel('Required bounded noise');axs[1].legend(frameon=False);fig.text(.125,.01,'Illustration uses u=0. With arbitrary common control, subtract its common response from every curve.\nThis large-error threshold hides the full phase family; it is not the optimal storage threshold.',fontsize=8);fig.tight_layout(rect=[0,.08,1,1]);fig.savefig(R/'figures/prefix_opacity.png');fig.savefig(R/'figures/prefix_opacity.pdf');plt.close(fig)
# Sensor first-detection uncertainty, analytical exact model only.
from scipy.optimize import brentq
etas=np.linspace(.0001,.12,200);taus=np.array([brentq(lambda z:z*np.exp(-z)-2*e,0,1) for e in etas]);fig,ax=plt.subplots(figsize=(7,4));ax.plot(etas,.1+taus,label='Post-detection edge interval width',c='#128b8b');ax.plot(etas,.05+.1+taus,label='Maximum delivered detection age',c='#b14343',ls='--');ax.scatter([.005,.01,.02,.05],[.1+brentq(lambda z:z*np.exp(-z)-2*e,0,1) for e in [.005,.01,.02,.05]],c='#128b8b');ax.set_xlabel('Bound on frequency sample error');ax.set_ylabel('Normalized time');ax.set_title('Robust inference replaces exact differentiation',loc='left',weight='bold');ax.legend(frameon=False,fontsize=9);fig.tight_layout();fig.savefig(R/'figures/detector_uncertainty.png');fig.savefig(R/'figures/detector_uncertainty.pdf');plt.close(fig)
